--
-- Table structure for table `contratos`
--

DROP TABLE IF EXISTS `contratos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `contratos` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `descripcion_contrato` varchar(1500) DEFAULT NULL,
  `dias_por_vencer` int DEFAULT NULL,
  `estado_contrato` enum('POR_VENCER_30','POR_VENCER_60','POR_VENCER_90','VENCIDO','VIGENTE') DEFAULT NULL,
  `fecha_actualizacion` datetime(6) DEFAULT NULL,
  `fecha_fin` date DEFAULT NULL,
  `fecha_inicio` date DEFAULT NULL,
  `fecha_registro` datetime(6) DEFAULT NULL,
  `impuesto` varchar(255) DEFAULT NULL,
  `meses` varchar(255) DEFAULT NULL,
  `moneda` varchar(255) DEFAULT NULL,
  `monto_contrato` decimal(16,2) DEFAULT NULL,
  `monto_total_mensual` decimal(14,2) DEFAULT NULL,
  `nombre_contrato` varchar(255) DEFAULT NULL,
  `numero_contrato` varchar(260) NOT NULL,
  `numero_interno` varchar(255) DEFAULT NULL,
  `observaciones` varchar(1200) DEFAULT NULL,
  `otros_gastos` decimal(14,2) DEFAULT NULL,
  `renta_mensual` decimal(14,2) DEFAULT NULL,
  `responsable_actas` varchar(255) DEFAULT NULL,
  `tipo_contrato` varchar(255) DEFAULT NULL,
  `proveedor_id` bigint DEFAULT NULL,
  `fecha_suscripcion` date DEFAULT NULL,
  `incluye_igv` bit(1) DEFAULT NULL,
  `area_presupuesto_gasto_comun` varchar(255) DEFAULT NULL,
  `area_presupuesto_renta` varchar(255) DEFAULT NULL,
  `centro_costo_gasto_comun` varchar(255) DEFAULT NULL,
  `centro_costo_renta` varchar(255) DEFAULT NULL,
  `cuenta_contable_gasto_comun` varchar(255) DEFAULT NULL,
  `cuenta_contable_renta` varchar(255) DEFAULT NULL,
  `tipo_gasto_gasto_comun` varchar(255) DEFAULT NULL,
  `tipo_gasto_renta` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_contrato_estado` (`estado_contrato`),
  KEY `idx_contrato_fin` (`fecha_fin`),
  KEY `FKicwabjl6iaiiokas7e8a91qc2` (`proveedor_id`),
  CONSTRAINT `FKicwabjl6iaiiokas7e8a91qc2` FOREIGN KEY (`proveedor_id`) REFERENCES `proveedores` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=733 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

